import{_ as h,o as t,c as i,a2 as c}from"./chunks/framework.CqpfiAoK.js";const e=JSON.parse('{"title":"Nguyên tắc chung của Hiến pháp Cộng sinh","description":"","frontmatter":{},"headers":[],"relativePath":"vi/40-共生宪法总纲.md","filePath":"vi/40-共生宪法总纲.md"}'),a={name:"vi/40-共生宪法总纲.md"};function g(u,n,p,l,o,r){return t(),i("div",null,[...n[0]||(n[0]=[c('<h1 id="nguyen-tac-chung-cua-hien-phap-cong-sinh" tabindex="-1">Nguyên tắc chung của Hiến pháp Cộng sinh <a class="header-anchor" href="#nguyen-tac-chung-cua-hien-phap-cong-sinh" aria-label="Permalink to &quot;Nguyên tắc chung của Hiến pháp Cộng sinh&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Dự án</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>40</td></tr><tr><td>Mô-đun</td><td>Hệ thống pháp luật và khuôn khổ quản trị</td></tr><tr><td>Từ khóa cốt lõi</td><td>Hiến pháp Cộng sinh, luật pháp cơ bản, bình đẳng mọi tộc, quyền cộng sinh, nguyên tắc hiến pháp</td></tr></tbody></table><h2 id="_1-vi-tri-hien-phap-va-boi-canh-ban-hanh" tabindex="-1">1. Vị trí hiến pháp và bối cảnh ban hành <a class="header-anchor" href="#_1-vi-tri-hien-phap-va-boi-canh-ban-hanh" aria-label="Permalink to &quot;1. Vị trí hiến pháp và bối cảnh ban hành&quot;">​</a></h2><p>《Hiến pháp Cộng sinh》 là luật pháp cơ bản của văn minh cộng sinh neo bên trong Vũ trụ Nguyên thủy Wanling Hengmao (Hengyuanzhou), có hiệu lực pháp luật cao nhất. Mọi luật pháp, quy định hành chính, quy định địa phương và quy định tự trị không được mâu thuẫn với hiến pháp; mọi tổ chức và cá nhân phải lấy hiến pháp làm tiêu chuẩn hoạt động cơ bản, và có nghĩa vụ duy trì phẩm giá hiến pháp cũng như đảm bảo việc thực thi hiến pháp.</p><p>Hiến pháp Cộng sinh được ban hành vào thời điểm văn minh cộng sinh neo chính thức thành lập, mục tiêu cốt lõi của nó là thiết lập ở cấp độ luật pháp cơ bản nền tảng văn minh &quot;phản đối cướp đoạt, đề xướng cộng sinh&quot;, và cố định bằng hình thức luật pháp cao nhất khái niệm cốt lõi của văn minh cộng sinh neo — trả lại quyền lựa chọn vận mệnh và tiến hóa cho mọi sự sống, nhiều lao động nhiều thu nhập, tự sinh tự trưởng, mọi người đều có con đường, mọi tộc cùng tiến bộ — để ngăn chặn sự phục hồi của hệ thống cướp đoạt.</p><h2 id="_2-nguyen-tac-co-ban-cua-hien-phap" tabindex="-1">2. Nguyên tắc cơ bản của hiến pháp <a class="header-anchor" href="#_2-nguyen-tac-co-ban-cua-hien-phap" aria-label="Permalink to &quot;2. Nguyên tắc cơ bản của hiến pháp&quot;">​</a></h2><p>Hiến pháp Cộng sinh đã thiết lập bảy nguyên tắc cơ bản, cấu thành nền tảng giá trị của toàn bộ hệ thống pháp luật:</p><table tabindex="0"><thead><tr><th>Nguyên tắc</th><th>Nội hàm</th></tr></thead><tbody><tr><td>Nguyên tắc bình đẳng mọi tộc</td><td>Mọi hình thái sự sống, bất kể tộc, trình độ tu luyện, xuất thân, đều bình đẳng trước pháp luật</td></tr><tr><td>Nguyên tắc tiến hóa cộng sinh</td><td>Tiến hóa cá nhân không được bằng cách tổn hại quyền tiến hóa của cá nhân hoặc tập thể khác</td></tr><tr><td>Nguyên tắc nhiều lao động nhiều thu nhập</td><td>Phân bổ nguồn lực lấy đóng góp làm cơ sở cốt lõi, phản đối hưởng thụ không lao động và chiếm đoạt kiểu cướp</td></tr><tr><td>Nguyên tắc tự sinh tự trưởng</td><td>Tôn trọng quyền lựa chọn tiến hóa tự chủ của mỗi sự sống, phản đối đồng hóa cưỡng bức và kiểm soát tư tưởng</td></tr><tr><td>Nguyên tắc mọi người đều có con đường</td><td>Nhà nước và văn minh có nghĩa vụ cung cấp cho mỗi sự sống con đường tiến hóa cơ bản và đảm bảo nguồn lực</td></tr><tr><td>Nguyên tắc lấy thực tế làm cơ sở</td><td>Pháp luật lấy thế giới thực làm cơ sở chân thực duy nhất, thiết kế hư cấu không có hiệu lực pháp luật</td></tr><tr><td>Nguyên tắc bền vững</td><td>Mọi phát triển phải cân nhắc tính bền vững của nguồn gốc vũ trụ, phản đối cạn kiệt nguồn lực</td></tr></tbody></table><h2 id="_3-quyen-co-ban-cua-cong-dan-moi-su-song" tabindex="-1">3. Quyền cơ bản của công dân (mọi sự sống) <a class="header-anchor" href="#_3-quyen-co-ban-cua-cong-dan-moi-su-song" aria-label="Permalink to &quot;3. Quyền cơ bản của công dân (mọi sự sống)&quot;">​</a></h2><p>Hiến pháp Cộng sinh trao cho mọi sự sống có khả năng cảm nhận bên trong Hengyuanzhou các quyền cơ bản sau:</p><ol><li><strong>Quyền lựa chọn tiến hóa</strong>: Mỗi sự sống có quyền tự do lựa chọn hệ thống tu luyện, con đường tiến hóa và lối sống, không tổ chức hay cá nhân nào được can thiệp cưỡng bức.</li><li><strong>Quyền được nguồn lực tu luyện</strong>: Mỗi sự sống có quyền được miễn phí các pháp môn cơ bản của ba trăm hệ thống tu luyện nguồn gốc, và thông qua cơ chế hợp đồng sản xuất liên hợp để được hỗ trợ nguồn lực tu luyện cần thiết.</li><li><strong>Quyền bảo vệ bình đẳng</strong>: Mỗi sự sống được hưởng待遇 bình đẳng trong việc áp dụng pháp luật, phân bổ nguồn lực, giáo dục y tế, v.v., cấm phân biệt đối xử dựa trên tộc, trình độ tu luyện, xuất thân.</li><li><strong>Quyền tham gia cộng sinh</strong>: Mỗi sự sống có quyền tham gia vào việc ra quyết định và giám sát các công việc công cộng, thông qua mạng lưới cộng sinh để thể hiện ý kiến, thực hiện quyền.</li><li><strong>Quyền bảo tồn văn hóa</strong>: Mỗi tộc và văn minh có quyền bảo tồn truyền thống văn hóa, ngôn ngữ chữ viết và phong tục tập quán của mình, văn minh cộng sinh tôn trọng đa dạng văn hóa.</li><li><strong>Quyền cứu trợ và khiếu nại</strong>: Mỗi sự sống khi quyền bị xâm phạm có quyền được cứu trợ thông qua hệ thống tư pháp, có quyền khiếu nại và tố cáo đối với các hành vi vi phạm pháp luật.</li></ol><h2 id="_4-nghia-vu-co-ban" tabindex="-1">4. Nghĩa vụ cơ bản <a class="header-anchor" href="#_4-nghia-vu-co-ban" aria-label="Permalink to &quot;4. Nghĩa vụ cơ bản&quot;">​</a></h2><p>Quyền và nghĩa vụ là tương đương, Hiến pháp Cộng sinh đồng thời quy định nghĩa vụ cơ bản của mọi sự sống:</p><ol><li><strong>Nghĩa vụ tuân thủ hiến pháp và pháp luật</strong></li><li><strong>Nghĩa vụ duy trì trật tự cộng sinh và lợi ích công cộng</strong></li><li><strong>Nghĩa vụ tham gia lao động và đóng góp theo pháp luật</strong> (mặt tương ứng của nhiều lao động nhiều thu nhập)</li><li><strong>Nghĩa vụ bảo vệ nguồn gốc vũ trụ và môi trường sinh thái</strong></li><li><strong>Nghĩa vụ tôn trọng quyền hợp pháp của các sự sống khác</strong></li><li><strong>Nghĩa vụ hướng dẫn người tu luyện sơ cấp trong phạm vi năng lực</strong> (nền tảng pháp luật của mạng lưới cố vấn)</li></ol><h2 id="_5-thiet-lap-co-quan-nha-nuoc-van-minh" tabindex="-1">5. Thiết lập cơ quan nhà nước (văn minh) <a class="header-anchor" href="#_5-thiet-lap-co-quan-nha-nuoc-van-minh" aria-label="Permalink to &quot;5. Thiết lập cơ quan nhà nước (văn minh)&quot;">​</a></h2><p>Hiến pháp Cộng sinh đã thiết lập cấu trúc quản trị của văn minh cộng sinh, thực hiện cơ chế phân lập và cân bằng ba quyền: &quot;Hội đồng nghị sự neo — Ủy ban điều hành cộng sinh — Tòa án cộng sinh&quot;:</p><ul><li><strong>Hội đồng nghị sự neo</strong>: Cơ quan quyền lực cao nhất, do đại diện mọi tộc cấu thành theo tỷ lệ, thực hiện quyền lập pháp và quyền quyết định các vấn đề重大</li><li><strong>Ủy ban điều hành cộng sinh</strong>: Cơ quan hành chính cao nhất, chịu trách nhiệm thi hành hiến pháp và pháp luật, quản trị hàng ngày</li><li><strong>Tòa án cộng sinh</strong>: Cơ quan tư pháp cao nhất, độc lập thực hiện quyền xét xử, chịu trách nhiệm xem xét vi hiến và xét xử các vụ án重大</li></ul><p>Ngoài ra, thành lập &quot;Ủy ban giám sát neo&quot; làm cơ quan giám sát độc lập, chịu trách nhiệm giám sát tất cả các cơ quan quyền lực, ngăn chặn lạm dụng quyền lực và sự phục hồi của hành vi cướp đoạt.</p><h2 id="_6-sua-đoi-va-đam-bao-hien-phap" tabindex="-1">6. Sửa đổi và đảm bảo hiến pháp <a class="header-anchor" href="#_6-sua-đoi-va-đam-bao-hien-phap" aria-label="Permalink to &quot;6. Sửa đổi và đảm bảo hiến pháp&quot;">​</a></h2><p>Việc sửa đổi Hiến pháp Cộng sinh phải được thông qua bởi đa số trên hai phần ba của Hội đồng nghị sự neo, và được đồng ý bởi hơn một nửa trong cuộc trưng cầu dân ý, mới có hiệu lực. Thủ tục nghiêm ngặt này đảm bảo sự ổn định của hiến pháp với tư cách là luật pháp cơ bản, ngăn chặn các nhóm lợi ích ngắn hạn dễ dàng thay đổi nền tảng văn minh.</p><p>Việc đảm bảo thực thi hiến pháp bao gồm: hệ thống xem xét vi hiến (Tòa án cộng sinh có quyền tuyên bố vô hiệu các luật pháp vi phạm hiến pháp), hệ thống tố tụng hiến pháp (mọi sự sống có thể trực tiếp khởi kiện dựa trên hiến pháp), hệ thống thề hiến pháp (tất cả công chức khi nhậm chức phải thề trung thành với hiến pháp).</p><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>《Hiến pháp Cộng sinh》 là viên đá nền tảng pháp luật của văn minh cộng sinh neo, đồng thời cũng là tuyên ngôn cao nhất của chủ nghĩa phản cướp đoạt. Nó đã chuyển hóa &quot;cộng sinh&quot; từ một khái niệm thành một hệ thống pháp luật có thể thực thi, có thể cứu trợ, có thể đảm bảo, cung cấp khuôn khổ pháp trị cơ bản cho sự tiến bộ chung của mọi tộc. Tất cả các luật ngành sau này đều lấy hiến pháp này làm cơ sở lập pháp.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>03-共生文明宪章 (Hiến chương Văn minh Cộng sinh)</li><li>41-共生劳动法 (Luật Lao động Cộng sinh)</li><li>48-司法体系与裁决机制 (Hệ thống Tư pháp và Cơ chế Phán quyết)</li><li>49-治理框架与权力制衡 (Khuôn khổ Quản trị và Cân bằng Quyền lực)</li></ul>',25)])])}const m=h(a,[["render",g]]);export{e as __pageData,m as default};
